/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { AnnihilationScreen } from "../../src/annihilation/AnnihilationScreen.js";
import { ComptonScreen } from "../../src/compton/ComptonScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import PhotonInteractionsColors from "../../src/PhotonInteractionsColors.js";
import { PairProductionScreen } from "../../src/pair-production/PairProductionScreen.js";
import { PhotonInteractionsPreferencesModel } from "../../src/preferences/PhotonInteractionsPreferencesModel.js";
import { XRayTubeScreen } from "../../src/xray-tube/XRayTubeScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from photonInteractionsQueryParameters.
  const simPreferences = new PhotonInteractionsPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new ComptonScreen({
      name: stringManager.getScreenNames().comptonStringProperty,
      tandem: Tandem.ROOT.createTandem("comptonScreen"),
      backgroundColorProperty: PhotonInteractionsColors.backgroundColorProperty,
      showEquationsProperty: simPreferences.showEquationsProperty,
    }),
    new XRayTubeScreen({
      name: stringManager.getScreenNames().xrayTubeStringProperty,
      tandem: Tandem.ROOT.createTandem("xrayTubeScreen"),
      backgroundColorProperty: PhotonInteractionsColors.backgroundColorProperty,
      showEquationsProperty: simPreferences.showEquationsProperty,
    }),
    new PairProductionScreen({
      name: stringManager.getScreenNames().pairProductionStringProperty,
      tandem: Tandem.ROOT.createTandem("pairProductionScreen"),
      backgroundColorProperty: PhotonInteractionsColors.backgroundColorProperty,
      showEquationsProperty: simPreferences.showEquationsProperty,
    }),
    new AnnihilationScreen({
      name: stringManager.getScreenNames().annihilationStringProperty,
      tandem: Tandem.ROOT.createTandem("annihilationScreen"),
      backgroundColorProperty: PhotonInteractionsColors.backgroundColorProperty,
      showEquationsProperty: simPreferences.showEquationsProperty,
    }),
  ];

  return { screens, tracked: { PhotonInteractionsColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
